python
import io
import os
from typing import Dict, Any, Tuple

from flask import Flask, request, send_file, jsonify, send_from_directory
from flask_cors import CORS
import requests
from werkzeug.utils import secure_filename

app = Flask(__name__, static_folder="static", static_url_path="/static")
CORS(app, resources={r"/*": {"origins": os.environ.get("ALLOWED_ORIGINS", "*")}})

DEFAULT_MODAL_URL = "https://example-modal-endpoint.modal.run/generate"
MODAL_URL = os.environ.get("MODAL_URL", DEFAULT_MODAL_URL)
REQUEST_TIMEOUT_SECONDS = int(os.environ.get("REQUEST_TIMEOUT_SECONDS", "300"))
MAX_UPLOAD_MB = int(os.environ.get("MAX_UPLOAD_MB", "50"))
MAX_PROMPT_LENGTH = int(os.environ.get("MAX_PROMPT_LENGTH", "1000"))
ALLOWED_IMAGE_MIME_PREFIX = "image/"
DEFAULT_PROMPT = "The scene comes to life with natural movement and realistic motion"
DEFAULT_NEGATIVE_PROMPT = "worst quality, inconsistent motion, blurry, jittery, distorted"
DEFAULT_WIDTH = "768"
DEFAULT_HEIGHT = "512"
DEFAULT_NUM_FRAMES = "121"
DEFAULT_NUM_STEPS = "40"
DEFAULT_GUIDANCE_SCALE = "4.0"
DEFAULT_FRAME_RATE = "24.0"


def validate_modal_url(url: str) -> str:
    if not url.startswith("https://"):
        raise RuntimeError("MODAL_URL must start with https://")
    return url


def get_limited_text(value: str, default: str, max_length: int) -> str:
    text = value if value is not None else default
    if len(text) > max_length:
        return text[:max_length]
    return text


def parse_int_field(form_value: str, default_str: str, field_name: str) -> int:
    raw_value = form_value if form_value is not None else default_str
    try:
        value = int(raw_value)
    except ValueError:
        raise ValueError(f"Invalid integer value for {field_name}")
    return value


def parse_float_field(form_value: str, default_str: str, field_name: str) -> float:
    raw_value = form_value if form_value is not None else default_str
    try:
        value = float(raw_value)
    except ValueError:
        raise ValueError(f"Invalid float value for {field_name}")
    return value


def build_modal_form_data(req) -> Dict[str, Any]:
    prompt = get_limited_text(
        req.form.get("prompt"), DEFAULT_PROMPT, MAX_PROMPT_LENGTH
    )
    negative_prompt = get_limited_text(
        req.form.get("negative_prompt"), DEFAULT_NEGATIVE_PROMPT, MAX_PROMPT_LENGTH
    )
    width = parse_int_field(req.form.get("width"), DEFAULT_WIDTH, "width")
    height = parse_int_field(req.form.get("height"), DEFAULT_HEIGHT, "height")
    num_frames = parse_int_field(
        req.form.get("num_frames"), DEFAULT_NUM_FRAMES, "num_frames"
    )
    num_inference_steps = parse_int_field(
        req.form.get("num_inference_steps"), DEFAULT_NUM_STEPS, "num_inference_steps"
    )
    guidance_scale = parse_float_field(
        req.form.get("guidance_scale"), DEFAULT_GUIDANCE_SCALE, "guidance_scale"
    )
    frame_rate = parse_float_field(
        req.form.get("frame_rate"), DEFAULT_FRAME_RATE, "frame_rate"
    )
    if width <= 0:
        raise ValueError("Width must be positive")
    if height <= 0:
        raise ValueError("Height must be positive")
    if num_frames <= 0:
        raise ValueError("Number of frames must be positive")
    if num_inference_steps <= 0:
        raise ValueError("Number of inference steps must be positive")
    if frame_rate <= 0:
        raise ValueError("Frame rate must be positive")
    return {
        "prompt": prompt,
        "negative_prompt": negative_prompt,
        "width": str(width),
        "height": str(height),
        "num_frames": str(num_frames),
        "num_inference_steps": str(num_inference_steps),
        "guidance_scale": str(guidance_scale),
        "frame_rate": str(frame_rate),
    }


def validate_uploaded_image() -> Tuple[Any, str, str]:
    if "image" not in request.files:
        raise ValueError("No image provided")
    image_file = request.files["image"]
    if image_file.filename is None or image_file.filename.strip() == "":
        raise ValueError("No file selected")
    if not image_file.content_type or not image_file.content_type.startswith(
        ALLOWED_IMAGE_MIME_PREFIX
    ):
        raise ValueError("File must be an image")
    filename = secure_filename(image_file.filename)
    image_file.stream.seek(0, os.SEEK_END)
    size_bytes = image_file.stream.tell()
    image_file.stream.seek(0)
    max_bytes = MAX_UPLOAD_MB * 1024 * 1024
    if size_bytes > max_bytes:
        raise ValueError("File too large")
    return image_file, filename, image_file.content_type


@app.route("/")
def index():
    return send_from_directory("static", "index.html")


@app.route("/generate", methods=["POST"])
def generate():
    try:
        image_file, filename, content_type = validate_uploaded_image()
    except ValueError as e:
        return jsonify({"error": str(e)}), 400
    try:
        form_data = build_modal_form_data(request)
    except ValueError as e:
        return jsonify({"error": str(e)}), 400
    try:
        validated_modal_url = validate_modal_url(MODAL_URL)
    except RuntimeError as e:
        return jsonify({"error": str(e)}), 500
    try:
        image_file.seek(0)
        files = {
            "file": (filename, image_file.stream, content_type)
        }
        response = requests.post(
            validated_modal_url,
            files=files,
            data=form_data,
            timeout=REQUEST_TIMEOUT_SECONDS,
        )
    except requests.exceptions.Timeout:
        return (
            jsonify(
                {"error": "Request timeout", "details": "Video generation took too long"}
            ),
            504,
        )
    except requests.exceptions.ConnectionError:
        return (
            jsonify(
                {
                    "error": "Connection error",
                    "details": "Failed to connect to backend video API",
                }
            ),
            503,
        )
    except requests.exceptions.RequestException:
        return (
            jsonify(
                {
                    "error": "Request failed",
                    "details": "Unexpected error talking to backend video API",
                }
            ),
            502,
        )
    if response.status_code != 200:
        error_body = None
        try:
            error_body = response.json()
        except ValueError:
            error_body = {"raw": response.text}
        return (
            jsonify(
                {
                    "error": "Backend error",
                    "status_code": response.status_code,
                    "backend": error_body,
                }
            ),
            response.status_code,
        )
    content_type_header = response.headers.get("Content-Type", "")
    if "video" not in content_type_header and not content_type_header.startswith(
        "application/octet-stream"
    ):
        return (
            jsonify(
                {
                    "error": "Invalid backend response type",
                    "content_type": content_type_header,
                }
            ),
            502,
        )
    video_bytes = response.content
    return send_file(
        io.BytesIO(video_bytes),
        mimetype="video/mp4",
        as_attachment=True,
        download_name="generated_video.mp4",
        max_age=0,
    )


@app.route("/health", methods=["GET"])
def health():
    try:
        validate_modal_url(MODAL_URL)
    except RuntimeError as e:
        return jsonify({"status": "unhealthy", "error": str(e)}), 500
    return jsonify({"status": "healthy"}), 200


if __name__ == "__main__":
    host = os.environ.get("FLASK_HOST", "0.0.0.0")
    port = int(os.environ.get("FLASK_PORT", "5000"))
    app.run(host=host, port=port, debug=False)
